function blockSizes(text) {
  const last = {}
  for (let i = 0; i < text.length; i++) last[text[i]] = i
  const sizes = []
  let start = 0
  let end = 0
  for (let i = 0; i < text.length; i++) {
    end = Math.max(end, last[text[i]])
    if (i === end) {
      sizes.push(i - start + 1)
      start = i + 1
    }
  }
  return sizes
}

